{"status":"edit","missing_fact":"","edits":[{"path":"logic.hpp","hash":"296bce35fd30d0b5de1b42b86222fcabd9f969511db74a519d5879d91feaca9a","old":"inline std::vector<std::vector<int>> merge_intervals(std::vector<std::vector<int>> intervals) { throw std::logic_error("implement interval merging"); }","new":"inline std::vector<std::vector<int>> merge_intervals(std::vector<std::vector<int>> intervals) {
    std::sort(intervals.begin(), intervals.end());
    std::vector<std::vector<int>> merged;
    for (const auto& interval : intervals) {
        if (merged.empty() || interval[0] > merged.back()[1]) {
            merged.push_back(interval);
        } else {
            merged.back()[1] = std::max(merged.back()[1], interval[1]);
        }
    }
    return merged;
}"}]}
